int LotVisitText::VariantCount(LotVisitText::Id nId)
{
    return s_Tables[nId].nVariants;
}

const char *LotVisitText::Get(LotVisitText::Id nId, int nVariant)
{
    int nLang = (unsigned char)GetLanguage();
    if (nLang < 1 || nLang > 20)
        nLang = 1;
    const Table &table = s_Tables[nId];
    if (nVariant < 0)
    {
        static bool s_bSeeded = false;
        if (!s_bSeeded)
        {
            srand((unsigned)time(0));
            s_bSeeded = true;
        }
        nVariant = table.nVariants > 1 ? rand() % table.nVariants : 0;
    }
    else if (nVariant >= table.nVariants)
        nVariant = 0;
    return table.pTexts[nVariant * 21 + nLang];
}
